select o.*, oa.detail_address as detail_address
from second_hand_trading.sh_order o
left join second_hand_trading.sh_idle_item i on o.idle_id = i.id
left join second_hand_trading.sh_user u_buyer on o.user_id = u_buyer.id
left join second_hand_trading.sh_user u_seller on i.user_id = u_seller.id
left join second_hand_trading.sh_order_address oa on oa.order_id = o.id


    and o.order_number LIKE CONCAT('%', #{orderNumber}, '%')


    and i.idle_name LIKE CONCAT('%', #{idleName}, '%')


    and o.order_price BETWEEN #{minPrice} AND #{maxPrice}


    and o.order_price >= #{minPrice}


    and o.order_price <= #{maxPrice}


    and u_buyer.nickname LIKE CONCAT('%', #{buyerNickname}, '%')


    and u_seller.nickname LIKE CONCAT('%', #{sellerNickname}, '%')


    and o.order_status = #{orderStatus}


    and o.payment_status = #{paymentStatus}


    and DATE(o.create_time) BETWEEN #{startTime} AND #{endTime}


    and DATE(o.create_time) >= #{startTime}


    and DATE(o.create_time) <= #{endTime}


order by o.id desc
limit #{begin}, #{nums}

select COUNT(*)
from second_hand_trading.sh_order o
left join second_hand_trading.sh_idle_item i on o.idle_id = i.id
left join second_hand_trading.sh_user u_buyer on o.user_id = u_buyer.id
left join second_hand_trading.sh_user u_seller on i.user_id = u_seller.id


    and o.order_number LIKE CONCAT('%', #{orderNumber}, '%')


    and i.idle_name LIKE CONCAT('%', #{idleName}, '%')


    and o.order_price BETWEEN #{minPrice} AND #{maxPrice}


    and o.order_price >= #{minPrice}


    and o.order_price <= #{maxPrice}


    and u_buyer.nickname LIKE CONCAT('%', #{buyerNickname}, '%')


    and u_seller.nickname LIKE CONCAT('%', #{sellerNickname}, '%')


    and o.order_status = #{orderStatus}


    and o.payment_status = #{paymentStatus}


    and DATE(o.create_time) BETWEEN #{startTime} AND #{endTime}


    and DATE(o.create_time) >= #{startTime}


    and DATE(o.create_time) <= #{endTime}

select o.id, o.order_number, o.user_id, o.idle_id, o.order_price, o.order_count, o.payment_status, o.payment_way, o.create_time, o.payment_time, o.order_status, o.is_deleted , oa.detail_address as detail_address from second_hand_trading.sh_order o left join second_hand_trading.sh_order_address oa on oa.order_id = o.id where o.idle_id in
#{id}
order by o.id desc
